import{_ as e,o as t,c as n,a2 as r}from"./chunks/framework.D66Xq0Kv.js";const m=JSON.parse('{"title":"14. Datamodellering och normalisering","description":"","frontmatter":{},"headers":[],"relativePath":"sv/chapters/14-datamodellering-och-normalisering.md","filePath":"sv/chapters/14-datamodellering-och-normalisering.md"}'),i={name:"sv/chapters/14-datamodellering-och-normalisering.md"};function s(l,a,o,d,p,k){return t(),n("div",null,[...a[0]||(a[0]=[r(`<h1 id="_14-datamodellering-och-normalisering" tabindex="-1">14. Datamodellering och normalisering <a class="header-anchor" href="#_14-datamodellering-och-normalisering" aria-label="Permalink to &quot;14. Datamodellering och normalisering&quot;">​</a></h1><p>En bokhandel behöver veta vilka produkter den säljer, vilka författare som skrivit böckerna och vilka produkttyper böckerna tillhör.</p><p>Vi skulle kunna lagra all information på varje produktrad. Då blir den lätt att läsa på ett ställe. Men om samma författare förekommer på hundra böcker behöver vi också skriva samma författarinformation hundra gånger.</p><p>Vad händer när författaren byter namn? Eller om vi vill registrera en författare som ännu inte har någon produkt i sortimentet?</p><p>När vi modellerar data behöver vi därför fråga oss: <strong>Vilken information hör till vilken företeelse?</strong></p><p>Normalisering syftar till att undvika onödig dubbellagring av data, skapa god dataintegritet och göra databasen lättare att förändra och bygga ut. Om vi lagrar ett sakförhållande på flera ställen kan vi behöva ändra det överallt – och riskerar att missa något.</p><p>Det finns flera <strong>normalformer</strong>. Varje normalform ställer ytterligare krav på hur informationen organiseras. Målet är inte att skapa så många tabeller som möjligt, utan att varje uppgift ska ha en tydlig plats och att samband ska kunna beskrivas utan onödig upprepning.</p><h2 id="grund" tabindex="-1">Grund <a class="header-anchor" href="#grund" aria-label="Permalink to &quot;Grund&quot;">​</a></h2><h3 id="egen-information-och-information-om-nagot-annat" tabindex="-1">Egen information och information om något annat <a class="header-anchor" href="#egen-information-och-information-om-nagot-annat" aria-label="Permalink to &quot;Egen information och information om något annat&quot;">​</a></h3><p>Tänk dig att vi börjar med en enda tabell för böcker:</p><p><strong>products</strong></p><table tabindex="0"><thead><tr><th>id</th><th>title</th><th style="text-align:right;">price</th><th>author_name</th><th>author_email</th><th>product_type</th></tr></thead><tbody><tr><td>1</td><td>Vägen hem</td><td style="text-align:right;">200.00</td><td>Anna Svensson</td><td>anna@authors.example</td><td>Roman</td></tr><tr><td>2</td><td>Den blå staden</td><td style="text-align:right;">150.00</td><td>Erik Lund</td><td>erik@authors.example</td><td>Roman</td></tr><tr><td>3</td><td>Vinterljus</td><td style="text-align:right;">249.00</td><td>Anna Svensson</td><td>anna@authors.example</td><td>Roman</td></tr><tr><td>4</td><td>Små historier</td><td style="text-align:right;">120.00</td><td>Erik Lund</td><td>erik@authors.example</td><td>Novellsamling</td></tr></tbody></table><p>Här blandar vi tre slags information:</p><ul><li>Produktens egen information: titel och pris.</li><li>Information om en annan företeelse: författarens namn och e-postadress.</li><li>En klassificering: produkttypen.</li></ul><p>Tabellen fungerar för våra fyra böcker. Men vissa uppgifter upprepas.</p><p>Att skilja mellan <strong>egen data och främmande data</strong> är en användbar första tanke när vi förbättrar modellen. Det är dock inte en fullständig definition av normalisering. För att förstå varför vi ska dela upp informationen behöver vi också undersöka beroenden mellan värden.</p><h3 id="nar-information-upprepas" tabindex="-1">När information upprepas <a class="header-anchor" href="#nar-information-upprepas" aria-label="Permalink to &quot;När information upprepas&quot;">​</a></h3><p>Anna Svenssons namn och e-postadress förekommer på två produktrader.</p><p>Det kan skapa flera problem:</p><p><strong>Uppdateringsproblem:</strong> Om Anna byter e-postadress måste vi ändra informationen på flera ställen. Missar vi ett av dem får databasen motstridiga uppgifter.</p><p><strong>Infogningsproblem:</strong> Om vi vill registrera en ny författare innan vi har en bok att koppla till författaren finns ingen naturlig rad att lägga informationen på.</p><p><strong>Borttagningsproblem:</strong> Om vi tar bort den sista boken av Erik Lund riskerar även den enda lagrade informationen om honom att försvinna.</p><p>Detta brukar kallas <em>anomalier</em>. De är tecken på att vår struktur kan behöva förändras.</p><h3 id="ge-forfattaren-en-egen-identitet" tabindex="-1">Ge författaren en egen identitet <a class="header-anchor" href="#ge-forfattaren-en-egen-identitet" aria-label="Permalink to &quot;Ge författaren en egen identitet&quot;">​</a></h3><p>Vi kan börja med att skapa en egen tabell för författare:</p><p><strong>authors</strong></p><table tabindex="0"><thead><tr><th>id</th><th>name</th><th>email</th></tr></thead><tbody><tr><td>1</td><td>Anna Svensson</td><td>anna@authors.example</td></tr><tr><td>2</td><td>Erik Lund</td><td>erik@authors.example</td></tr></tbody></table><p>Då behöver vi inte skriva författarens namn och e-postadress på varje produkt.</p><p>Men hur kopplar vi produkten till författaren?</p><p>Vi skulle kunna lagra <code>author_id</code> i <code>products</code>. Det fungerar om varje produkt alltid har exakt en författare.</p><p>I vår bokhandel vill vi däremot kunna hantera böcker med flera författare.</p><h3 id="en-kopplingstabell-for-flera-till-flera" tabindex="-1">En kopplingstabell för flera-till-flera <a class="header-anchor" href="#en-kopplingstabell-for-flera-till-flera" aria-label="Permalink to &quot;En kopplingstabell för flera-till-flera&quot;">​</a></h3><p>I stället skapar vi <code>product_authors</code>:</p><p><strong>product_authors</strong></p><table tabindex="0"><thead><tr><th>product_id</th><th>author_id</th></tr></thead><tbody><tr><td>1</td><td>1</td></tr><tr><td>2</td><td>2</td></tr><tr><td>3</td><td>1</td></tr><tr><td>4</td><td>2</td></tr></tbody></table><p>Den innehåller relationer mellan produkter och författare.</p><p>Om en bok skrivits av två författare registrerar vi helt enkelt två kopplingar till samma produkt.</p><p>Med SQL kan vi uttrycka tabellen så här:</p><div class="language-sql vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">CREATE</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> TABLE</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> product_authors</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    product_id </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">INTEGER</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> NOT NULL</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    author_id </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">INTEGER</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> NOT NULL</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    PRIMARY KEY</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (product_id, author_id),</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    FOREIGN KEY</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (product_id)</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">        REFERENCES</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> products(id),</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    FOREIGN KEY</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (author_id)</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">        REFERENCES</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> authors(id)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span></code></pre></div><p>Nu kan en författare finnas oberoende av produkterna, samtidigt som en produkt kan ha flera författare.</p><p>Vi har alltså inte bara <em>flyttat kolumner</em>. Vi har gjort relationen mellan företeelserna tydligare.</p><h3 id="referensdata-har-ocksa-en-egen-plats" tabindex="-1">Referensdata har också en egen plats <a class="header-anchor" href="#referensdata-har-ocksa-en-egen-plats" aria-label="Permalink to &quot;Referensdata har också en egen plats&quot;">​</a></h3><p>Vi har tidigare skapat tabellen <code>product_types</code>:</p><table tabindex="0"><thead><tr><th>id</th><th>name</th></tr></thead><tbody><tr><td>1</td><td>Roman</td></tr><tr><td>2</td><td>Novellsamling</td></tr></tbody></table><p>I <code>products</code> lagrar vi därför <code>product_type_id</code>, inte typnamnet på varje rad.</p><p>Produkttypen är här <strong>referensdata</strong>: en kategori som används för att beskriva produkterna.</p><p>En författare är däremot inte bara ett tillåtet kategorivärde. Författaren är en självständig företeelse med egna attribut och en egen identitet.</p><p>Det är en av anledningarna till att samma sorts relationsteknik kan användas för olika informationsbegrepp.</p><h3 id="var-uppdelade-modell" tabindex="-1">Vår uppdelade modell <a class="header-anchor" href="#var-uppdelade-modell" aria-label="Permalink to &quot;Vår uppdelade modell&quot;">​</a></h3><p>Den modell vi nu använder kan beskrivas så här:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>products</span></span>
<span class="line"><span>    id</span></span>
<span class="line"><span>    title</span></span>
<span class="line"><span>    price</span></span>
<span class="line"><span>    stock</span></span>
<span class="line"><span>    product_type_id  → product_types.id</span></span>
<span class="line"><span></span></span>
<span class="line"><span>product_types</span></span>
<span class="line"><span>    id</span></span>
<span class="line"><span>    name</span></span>
<span class="line"><span></span></span>
<span class="line"><span>authors</span></span>
<span class="line"><span>    id</span></span>
<span class="line"><span>    name</span></span>
<span class="line"><span>    email</span></span>
<span class="line"><span></span></span>
<span class="line"><span>product_authors</span></span>
<span class="line"><span>    product_id       → products.id</span></span>
<span class="line"><span>    author_id        → authors.id</span></span></code></pre></div><p>En produkt har en produkttyp, och en produkttyp kan beskriva flera produkter.</p><p>En produkt kan ha flera författare, och en författare kan vara kopplad till flera produkter.</p><p>Vi kan sedan använda <code>JOIN</code> för att visa informationen tillsammans:</p><div class="language-sql vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">SELECT</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    p</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">title</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    a</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">name</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> AS</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> author_name</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">FROM</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> products </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">AS</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> p</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">INNER JOIN</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> product_authors </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">AS</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> pa</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    ON</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> pa</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">product_id</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> p</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">id</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">INNER JOIN</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> authors </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">AS</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> a</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    ON</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> a</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">id</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> pa</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">author_id</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span></code></pre></div><p>Att informationen är uppdelad betyder alltså inte att vi förlorat möjligheten att använda den som en helhet.</p><h3 id="normalformerna-–-fran-enkla-regler-till-tydligare-struktur" tabindex="-1">Normalformerna – från enkla regler till tydligare struktur <a class="header-anchor" href="#normalformerna-–-fran-enkla-regler-till-tydligare-struktur" aria-label="Permalink to &quot;Normalformerna – från enkla regler till tydligare struktur&quot;">​</a></h3><p>Vi kan beskriva de första tre normalformerna med tre korta frågor:</p><table tabindex="0"><thead><tr><th>Normalform</th><th>Fråga</th></tr></thead><tbody><tr><td><strong>1NF</strong></td><td>Innehåller varje cell ett enskilt värde, eller har vi grupperat flera värden i samma kolumn?</td></tr><tr><td><strong>2NF</strong></td><td>Hör alla icke-nyckelattribut till <strong>hela</strong> nyckeln, eller beskriver något bara en del av den?</td></tr><tr><td><strong>3NF</strong></td><td>Beror ett attribut direkt på nyckeln, eller beskriver det egentligen något som bestäms av ett annat attribut?</td></tr></tbody></table><p>Vi börjar med denna praktiska förståelse och undersöker sedan hur kraven kan beskrivas mer exakt.</p><h3 id="forsta-normalformen-en-uppgift-per-varde" tabindex="-1">Första normalformen: en uppgift per värde <a class="header-anchor" href="#forsta-normalformen-en-uppgift-per-varde" aria-label="Permalink to &quot;Första normalformen: en uppgift per värde&quot;">​</a></h3><p>Anta att vi registrerar författare så här:</p><table tabindex="0"><thead><tr><th>product_id</th><th>title</th><th>authors</th></tr></thead><tbody><tr><td>1</td><td>Vägen hem</td><td>Anna Svensson, Erik Lund</td></tr></tbody></table><p>Kolumnen <code>authors</code> innehåller här en kommaseparerad lista av författare.</p><p>Det verkar praktiskt, men det blir svårt att identifiera varje författare och kontrollera relationerna mellan produkter och författare.</p><p>Vi vill i stället representera författarna var för sig och lagra varje koppling som en egen rad i <code>product_authors</code>.</p><p>Det här illustrerar <strong>första normalformen (1NF)</strong>: varje cell ska innehålla ett <strong>atomärt värde</strong> – inte en lista av flera författare som vi förväntas behandla var för sig.</p><p>Vad som räknas som atomärt avgörs av datamodellen och vilka operationer vi behöver kunna utföra. En textsträng eller ett datum kan exempelvis vara ett enda värde även om det går att dela upp i tecken eller datumdelar.</p><h3 id="andra-normalformen-beroende-pa-hela-nyckeln" tabindex="-1">Andra normalformen: beroende på hela nyckeln <a class="header-anchor" href="#andra-normalformen-beroende-pa-hela-nyckeln" aria-label="Permalink to &quot;Andra normalformen: beroende på hela nyckeln&quot;">​</a></h3><p>Tänk att vi skapar följande tabell:</p><table tabindex="0"><thead><tr><th>product_id</th><th>author_id</th><th>product_title</th><th>author_name</th></tr></thead><tbody><tr><td>1</td><td>1</td><td>Vägen hem</td><td>Anna Svensson</td></tr><tr><td>1</td><td>2</td><td>Vägen hem</td><td>Erik Lund</td></tr></tbody></table><p>Vi antar att kombinationen <code>(product_id, author_id)</code> identifierar varje rad.</p><p>Men <code>product_title</code> beror bara på <code>product_id</code>. Och <code>author_name</code> beror bara på <code>author_id</code>.</p><p>Informationen hör alltså inte till <em>hela kombinationen</em>. Den hör till varsin företeelse.</p><p>Genom att flytta titel till <code>products</code> och namn till <code>authors</code> och behålla <code>product_authors</code> som en ren koppling kan vi undvika dessa <strong>partiella beroenden</strong>.</p><p>Det är grundidén bakom <strong>andra normalformen (2NF)</strong>: ett icke-nyckelattribut ska beskriva något som hör till <strong>hela</strong> nyckeln.</p><p>Som praktisk tumregel kan vi fråga oss om tabellen verkligen beskriver en och samma företeelse eller relation. Men 2NF handlar mer specifikt om <strong>partiella beroenden av sammansatta kandidatnycklar</strong>. En tabell kan uppfylla 2NF och ändå innehålla information om andra företeelser som gör att den bryter mot 3NF.</p><h3 id="tredje-normalformen-beroenden-via-andra-attribut" tabindex="-1">Tredje normalformen: beroenden via andra attribut <a class="header-anchor" href="#tredje-normalformen-beroenden-via-andra-attribut" aria-label="Permalink to &quot;Tredje normalformen: beroenden via andra attribut&quot;">​</a></h3><p>Anta att vi har:</p><table tabindex="0"><thead><tr><th>product_id</th><th>title</th><th>product_type_id</th><th>product_type_name</th></tr></thead><tbody><tr><td>1</td><td>Vägen hem</td><td>1</td><td>Roman</td></tr><tr><td>3</td><td>Vinterljus</td><td>1</td><td>Roman</td></tr><tr><td>4</td><td>Små historier</td><td>2</td><td>Novellsamling</td></tr></tbody></table><p>Vi har <code>product_id</code> som primärnyckel.</p><p>Produkttypens namn bestäms av <code>product_type_id</code>. Det finns alltså ett beroende från produktens identifierare till typ-id, och vidare från typ-id till typnamnet.</p><p>Vi kan undvika upprepningen genom att lägga <code>product_type_name</code> i <code>product_types</code> och bara lagra <code>product_type_id</code> i <code>products</code>.</p><p>Det är grundtanken bakom <strong>tredje normalformen (3NF)</strong>: en uppgift ska inte vara indirekt beroende av nyckeln via ett annat icke-nyckelattribut.</p><p>Produktens typ-id beskriver vilken typ produkten tillhör. Typens namn beskriver däremot själva produkttypen, inte produkten. Vi lagrar därför namnet i <code>product_types</code>.</p><p>Detta är en användbar förenkling. Den mer exakta definitionen, som också tar hänsyn till kandidatnycklar, följer under <em>Avancerat</em>.</p><h2 id="avancerat" tabindex="-1">Avancerat <a class="header-anchor" href="#avancerat" aria-label="Permalink to &quot;Avancerat&quot;">​</a></h2><h3 id="funktionella-beroenden" tabindex="-1">Funktionella beroenden <a class="header-anchor" href="#funktionella-beroenden" aria-label="Permalink to &quot;Funktionella beroenden&quot;">​</a></h3><p>För att förstå normalisering mer noggrant behöver vi begreppet <strong>funktionellt beroende</strong>.</p><p>Vi skriver:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>product_id → title, price, stock</span></span></code></pre></div><p>Det betyder att ett bestämt <code>product_id</code> avgör vilka värden <code>title</code>, <code>price</code> och <code>stock</code> har i vår modell.</p><p>Vi kan också skriva:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>author_id → name, email</span></span></code></pre></div><p>Det betyder inte att en författare aldrig kan byta namn eller e-postadress. Det betyder att varje identifierad författare vid en given tidpunkt har ett bestämt värde för de attribut som vi modellerar.</p><p>Ett funktionellt beroende handlar alltså om de regler vi förutsätter för vår information, inte bara om vilka råkar vara de aktuella värdena i databasen.</p><h3 id="kandidatnycklar-och-en-mer-precis-syn-pa-normalformerna" tabindex="-1">Kandidatnycklar och en mer precis syn på normalformerna <a class="header-anchor" href="#kandidatnycklar-och-en-mer-precis-syn-pa-normalformerna" aria-label="Permalink to &quot;Kandidatnycklar och en mer precis syn på normalformerna&quot;">​</a></h3><p>En <strong>kandidatnyckel</strong> är en minimal uppsättning attribut som kan identifiera en rad unikt.</p><p>En tabell kan ha flera kandidatnycklar. Den vi väljer som primärnyckel är bara en av dem.</p><p>I mer formell terminologi handlar 2NF om att varje attribut som inte ingår i någon kandidatnyckel är fullt funktionellt beroende av varje kandidatnyckel.</p><p>3NF kräver dessutom att för varje icke-trivialt funktionellt beroende <code>X → A</code> gäller att <code>X</code> är en supernyckel eller att <code>A</code> är ett <em>primattribut</em>, alltså ingår i någon kandidatnyckel.</p><p>Det innebär att den vanliga minnesregeln om ”beroende av nyckeln och inget annat än nyckeln” är användbar, men inte en fullständig definition.</p><h3 id="boyce–codd-och-hogre-normalformer" tabindex="-1">Boyce–Codd och högre normalformer <a class="header-anchor" href="#boyce–codd-och-hogre-normalformer" aria-label="Permalink to &quot;Boyce–Codd och högre normalformer&quot;">​</a></h3><p><strong>Boyce–Codd-normalformen (BCNF)</strong> skärper kravet på funktionella beroenden: varje determinant i ett icke-trivialt funktionellt beroende ska vara en supernyckel.</p><p><strong>Fjärde normalformen (4NF)</strong> tar upp situationer där flera <em>oberoende flervärdesfakta</em> lagras tillsammans. Anta exempelvis att en produkt kan ha flera författare och samtidigt finnas i flera språkversioner, och att relationerna är oberoende av varandra. Om vi lagrar alla kombinationer av författare och språk i en enda tabell kan vi skapa onödig upprepning. Då kan separata relationer vara bättre.</p><p><strong>Femte normalformen (5NF)</strong> handlar om relationer där <strong>tre eller fler samband tillsammans</strong> avgör vilka kombinationer som är giltiga.</p><p>Föreställ dig att bokhandeln har flera butiker och leverantörer. Vi vill beskriva vilka leverantörer som kan leverera vilka produkter till vilka butiker. Vi börjar med en tabell:</p><table tabindex="0"><thead><tr><th>supplier_id</th><th>product_id</th><th>store_id</th></tr></thead><tbody><tr><td>1</td><td>10</td><td>1</td></tr><tr><td>1</td><td>10</td><td>2</td></tr><tr><td>1</td><td>20</td><td>1</td></tr></tbody></table><p>Varje rad beskriver en kombination av <em>leverantör, produkt och butik</em>.</p><p>Anta nu att verksamheten har en bestämd regel: <strong>Om en leverantör kan leverera en produkt, leverantören samarbetar med en butik och butiken tar emot produkten, då gäller också kombinationen av alla tre.</strong></p><p>Då beskriver vår tabell egentligen tre slags samband:</p><ul><li>Vilka <strong>produkter</strong> varje <strong>leverantör</strong> kan leverera.</li><li>Vilka <strong>butiker</strong> varje <strong>leverantör</strong> samarbetar med.</li><li>Vilka <strong>produkter</strong> varje <strong>butik</strong> tar emot.</li></ul><p>Vi skulle kunna lagra dessa samband i tre separata tabeller. En <code>JOIN</code> mellan samtliga tre kan då återskapa exakt de giltiga kombinationerna av leverantör, produkt och butik. Om vi behåller allt i samma tabell upprepar vi i stället samband som redan bestäms av de andra.</p><p>Det kallas ett <strong>joinberoende</strong>: en relation kan återskapas fullständigt genom att kombinera flera mindre relationer, utan att vi förlorar information eller skapar ogiltiga kombinationer.</p><p>Det avgörande är <strong>verksamhetsregeln</strong>. Om bokhandeln i stället avtalar varje enskild kombination av leverantör, produkt och butik separat, kan vi inte härleda alla kombinationer från de tre parvisa sambanden. Då skulle uppdelningen kunna skapa leveranser som aldrig avtalats.</p><p>5NF hjälper oss alltså att upptäcka när en komplex relation i själva verket kan beskrivas av flera mindre, oberoende relationer – <strong>men bara när vi vet att uppdelningen är giltig för alla tillåtna datatillstånd</strong>, inte bara för de exempelrader vi råkar ha just nu.</p><p>Det är alltså inte korrekt att 4NF bara betyder ”använd en kopplingstabell” eller att 5NF betyder ”ha flera kopplingar mellan samma entiteter”. Båda handlar om vilka beroenden som faktiskt gäller i informationen.</p><p>I de flesta praktiska databasprojekt är en genomtänkt modell som uppfyller 3NF en bra utgångspunkt, även om högre normalformer och medveten denormalisering ibland behöver övervägas.</p><p>För en mer utförlig men fortfarande pedagogisk förklaring av normalformerna rekommenderas William Kents <em>A Simple Guide to Five Normal Forms in Relational Database Theory</em>.[^kent]</p><p>[^kent]: William Kent, <em>A Simple Guide to Five Normal Forms in Relational Database Theory</em>, Communications of the ACM 26(2), 1983, s. 120–125. Tillgänglig på <a href="https://knowledge.kitchen/content/courses/database-design/normal-forms-simple-guide/" target="_blank" rel="noreferrer">https://knowledge.kitchen/content/courses/database-design/normal-forms-simple-guide/</a>.</p><h3 id="normalisering-ar-inte-bara-att-dela-upp-tabeller" tabindex="-1">Normalisering är inte bara att dela upp tabeller <a class="header-anchor" href="#normalisering-ar-inte-bara-att-dela-upp-tabeller" aria-label="Permalink to &quot;Normalisering är inte bara att dela upp tabeller&quot;">​</a></h3><p>En modell med fler tabeller är inte automatiskt bättre normaliserad.</p><p>Om vi delar upp information utan att förstå beroendena kan vi skapa onödig komplexitet.</p><p>Vi kan också få problem om vi delar upp något som i verksamheten faktiskt är ett sammanhängande värde, eller om vi skapar otydliga identiteter och relationer.</p><p>Normalisering handlar om att <strong>bevara informationens betydelse och beroenden</strong> när vi organiserar den.</p><p>Ett bra mål är att en förändring av ett sakförhållande normalt ska behöva göras på ett enda logiskt ställe.</p><h3 id="nar-relationen-har-egna-attribut" tabindex="-1">När relationen har egna attribut <a class="header-anchor" href="#nar-relationen-har-egna-attribut" aria-label="Permalink to &quot;När relationen har egna attribut&quot;">​</a></h3><p>Föreställ dig att vi vill veta i vilken ordning författarna ska visas på en bok.</p><p>Då räcker det inte att bara veta vilka författare som hör till produkten. Vi behöver också beskriva <strong>relationen</strong>.</p><p>Vi kan lägga till <code>author_order</code> i <code>product_authors</code>:</p><div class="language-sql vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">CREATE</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> TABLE</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> product_authors</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    product_id </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">INTEGER</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> NOT NULL</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    author_id </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">INTEGER</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> NOT NULL</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    author_order </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">INTEGER</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> NOT NULL</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    PRIMARY KEY</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (product_id, author_id),</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    FOREIGN KEY</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (product_id)</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">        REFERENCES</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> products(id),</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    FOREIGN KEY</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (author_id)</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">        REFERENCES</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> authors(id),</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    CHECK</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (author_order </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">),</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    UNIQUE</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (product_id, author_order)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span></code></pre></div><p><code>author_order</code> beskriver inte författaren som person och inte heller produkten ensam. Det beskriver författarens plats <strong>i förhållande till en viss produkt</strong>.</p><p>Det är ett exempel på att även en relation kan ha egna meningsfulla attribut.</p><h3 id="normalisering-och-historisk-information" tabindex="-1">Normalisering och historisk information <a class="header-anchor" href="#normalisering-och-historisk-information" aria-label="Permalink to &quot;Normalisering och historisk information&quot;">​</a></h3><p>Anta att vi kopplar en orderrad direkt till produktens aktuella pris.</p><p>Om priset ändras i <code>products</code> skulle en senare fråga kunna ge intryck av att kunden betalade det nya priset vid den tidigare beställningen.</p><p>Därför kan vi behöva lagra <strong>priset vid köptillfället</strong> på orderraden, även om produktens aktuella pris redan finns i en annan tabell.</p><p>Det är inte nödvändigtvis onödig dubbellagring. Det är två olika sakförhållanden:</p><ul><li>Aktuellt pris på en produkt.</li><li>Avtalat pris på en orderrad vid en viss tidpunkt.</li></ul><p>Att lagra båda kan därför vara helt förenligt med en genomtänkt datamodell.</p><p>Normalisering betyder inte att alla värden som ser likadana ut måste lagras på exakt ett ställe. Vi behöver först förstå <strong>vad de olika värdena betyder</strong>.</p><h3 id="normalisering-och-praktisk-prestanda" tabindex="-1">Normalisering och praktisk prestanda <a class="header-anchor" href="#normalisering-och-praktisk-prestanda" aria-label="Permalink to &quot;Normalisering och praktisk prestanda&quot;">​</a></h3><p>Det kan finnas skäl att skapa särskilda, beräknade eller duplicerade representationer för rapportering och prestanda.</p><p>Det brukar kallas <strong>denormalisering</strong> när vi medvetet inför redundans eller förenklar en struktur för att stödja ett visst användningssätt.</p><p>Men först behöver vi veta vilken grundmodell och vilka beroenden vi utgår från. Annars är det svårt att avgöra vilka avvikelser vi gör och vilka problem de kan skapa.</p><p>I senare kapitel kommer vi att använda Views och andra tekniker för att erbjuda enklare representationer utan att alltid behöva förändra lagringsmodellen.</p><h2 id="reflektion" tabindex="-1">Reflektion <a class="header-anchor" href="#reflektion" aria-label="Permalink to &quot;Reflektion&quot;">​</a></h2><ol><li>Hur kan vi avgöra om en uppgift beskriver produkten själv, författaren eller relationen mellan dem?</li><li>När är upprepade värden ett problem, och när kan två lika värden representera olika sakförhållanden?</li><li>Varför bör vi förstå informationens beroenden innan vi bestämmer hur många tabeller modellen ska innehålla?</li></ol>`,148)])])}const g=e(i,[["render",s]]);export{m as __pageData,g as default};
